"use strict";(self.webpackChunkunderdog_react=self.webpackChunkunderdog_react||[]).push([["5754"],{7793:function(e,t,s){s.d(t,{Z:()=>r});var a=s(52676);s(75271);var n=s(54461),o=s(95905);let i={linkWrapper:"styles__linkWrapper__pspMS",link:"styles__link__UsTZG",arrowIcon:"styles__arrowIcon__gMrDL"},r=e=>{let{className:t,href:s,showArrow:r,text:l}=e;return(0,a.jsxs)("span",{className:i.linkWrapper,children:[(0,a.jsx)("a",{className:(0,n.Z)(i.link,t),"data-testid":"external-link",href:s,rel:"noopener noreferrer",target:"_blank",children:l}),r&&(0,a.jsx)(o.Z,{className:i.arrowIcon,name:"arrowOutwardFilled"})]})}},14446:function(e,t,s){s.d(t,{Z:()=>r});var a=s(52676);s(75271);var n=s(54461),o=s(95905);let i={logo:"styles__logo__YOe5c",light:"styles__light__xd0dg",dark:"styles__dark__Es5Fi",invertedMode:"styles__invertedMode__SO5bt"},r=e=>{let{className:t,forcedTheme:s,isModeInverted:r}=e;return s?(0,a.jsx)("span",{"aria-hidden":"true",className:t,children:(0,a.jsx)(o.Z,{name:"light"===s?"logoIconLightMode":"logoIconDarkMode"})}):(0,a.jsxs)("span",{"aria-hidden":"true",className:(0,n.Z)(i.logo,r?i.invertedMode:"",t),children:[(0,a.jsx)(o.Z,{className:i.light,name:"logoIconLightMode"}),(0,a.jsx)(o.Z,{className:i.dark,name:"logoIconDarkMode"})]})}},55370:function(e,t,s){s.d(t,{Z:()=>o});var a=s(52676);s(75271);var n=s(42748);let o=e=>{let{title:t,description:s,defer:o=!0}=e,i=`https://app.underdogsports.com${window.location.pathname}`;return(0,a.jsxs)(n.q,{defer:o,children:[(0,a.jsx)("title",{children:t||"Underdog Sports"}),(0,a.jsx)("meta",{content:s||"Underdog Sports is the best place to play best ball. Available on iOS, Android and Web.",name:"description"}),(0,a.jsx)("link",{href:i,rel:"canonical"})]})}},70458:function(e,t,s){s.r(t),s.d(t,{default:()=>u});var a=s(52676),n=s(75271),o=s(56770),i=s(7793),r=s(14446),l=s(55370),h=s(57099);let d="styles__externalLink__Sozw6",c="styles__subheading__Ak3TR",p="styles__text__rzV2N",f="styles__italic__zvt1W",g="styles__quoteText__bdy7i",m="styles__endNote__Z_Ksv",u=()=>((0,n.useEffect)(()=>{o.iND.contestLegalityLetterOpened()},[]),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(l.Z,{title:"Contest Legality"}),(0,a.jsx)("div",{className:"styles__contestLegalityLetter__vBcdb",children:(0,a.jsxs)("div",{className:"styles__letter__wntmp",children:[(0,a.jsxs)("div",{className:"styles__letterHeader__YlEPT",children:[(0,a.jsx)(r.Z,{className:"styles__logo__f1KoD",forcedTheme:"light"}),(0,a.jsxs)("div",{className:"styles__authorInfo__o34Jz",children:[(0,a.jsx)("p",{className:"styles__name__F3Vu3",children:"Nicholas G. Green"}),(0,a.jsx)("p",{children:"General Counsel"}),(0,a.jsx)("p",{children:"Underdog Sports Holdings, Inc."})]})]}),(0,a.jsx)("p",{className:"styles__letterTitle___nhkC",children:"The Legal Framework & Analysis for Underdog's Pick'em Fantasy Contests"}),(0,a.jsx)("p",{className:"styles__date__ISi7p",children:"September 2023"}),(0,a.jsxs)("p",{className:p,children:["The intersection between paid fantasy sports and sports betting has been a hot topic in our industry. This paper adds my perspective to the narrative offered by Underdog's competitors. My perspective comes from working to establish U.S. fantasy sports and sports betting laws since 2015, specifically from being part of the legal team that developed the legislation that became the basis for fantasy sports and sports betting laws in more than two-dozen states. Below is a breakdown of the law, and how the law applies to Underdog's contests and similar fantasy sports generally.",(0,a.jsx)("a",{href:"#footnote_one",rel:"noopener",children:(0,a.jsx)("sup",{children:"1"})})]}),(0,a.jsx)("p",{className:c,children:"Key Points:"}),(0,a.jsxs)("ul",{children:[(0,a.jsx)("li",{className:p,children:"Underdog's fantasy contests, including our Pick'em fantasy contests, comply with the letter and spirit of state and federal law everywhere that we offer them. Further, Underdog holds all licenses and governmental permissions necessary to offer our contests, including licenses and permits for fantasy contests in every state that requires them."}),(0,a.jsx)("li",{className:p,children:"Laws protecting fantasy sports have never encompassed a single format of contests. Legislatures drafted the definitions for fantasy sports broadly to allow myriad existing and future formats."}),(0,a.jsx)("li",{className:p,children:"Federal law expressly excludes fantasy sports from the law prohibiting unlawful internet gambling. If a fantasy contest satisfies the conditions provided in the Unlawful Internet Gambling Enforcement Act, commonly known as the “UIGEA carve out,” then it is not a form of “gambling” under federal law. 31 U.S.C. \xa7 5362(1)(E)(ix)."}),(0,a.jsxs)("li",{className:p,children:["Underdog's Pick'em fantasy contests meet the letter of the accepted definition of fantasy sports because they are",(0,a.jsxs)("ul",{children:[(0,a.jsx)("li",{className:p,children:"contests of skill,"}),(0,a.jsx)("li",{className:p,children:"in which patrons create rosters of multiple athletes from different teams,"}),(0,a.jsx)("li",{className:p,children:"who play in real-world athletic contests, and"}),(0,a.jsx)("li",{className:p,children:"the winning outcomes are based on how all of the selected real-world athletes perform in the aggregate."})]})]}),(0,a.jsx)("li",{className:p,children:"If a contest satisfies the definition of “fantasy sports,” then it cannot be considered sports betting as a matter of law. Nearly every state sports betting law expressly exempts fantasy sports from its definition of sports wagering. The legal analysis begins and ends with the threshold question of whether the product is a fantasy sports contest, which Underdog's games squarely satisfy."}),(0,a.jsx)("li",{className:p,children:"Additionally, our Pick'em fantasy games have been tested and validated statistically as contests of skill, in which skill predominates over chance, by the same statistician using the same methodology employed by DraftKings in high-profile litigation in New York and Texas."}),(0,a.jsx)("li",{className:p,children:"In 2015, opponents of paid daily fantasy sports tried to label them as sports betting, making essentially the same arguments that DraftKings and FanDuel are making today in opposition to Underdog's Pick'em fantasy contests. Just as those opponents were wrong then, the incumbents are wrong now: There are dramatic and legally significant differences between Underdog's fantasy contests and what is available on casino sportsbooks like DraftKings and FanDuel. For example, fantasy sports patrons cannot mix-and-match player predictions with wagers on team or game statistics."}),(0,a.jsx)("li",{className:p,children:"Regardless of whether a contest “looks” like sports betting, the legal analysis disregards optics and focuses instead on the letter of the law. Taken to an extreme, all paid fantasy sports could be construed as a form of sports wagering, which is plainly not the law. That is why legislatures have been careful to exclude paid fantasy sports from their description of what constitutes sports wagering."}),(0,a.jsxs)("li",{className:p,children:["Neither federal nor state law creates a black and white rule that fantasy sports are “peer to peer” while sports betting is “against the house,” as opponents of Pick'em fantasy contests claim. Had Congress or the states where we offer Pick'em fantasy contests intended such a result, they would have said so. Regardless, these arguments overlook the critical role that the fantasy sports operator always played in setting the terms and backing the prizes in",(0,a.jsx)("span",{className:f,children:"all"})," fantasy sports formats."]}),(0,a.jsx)("li",{className:p,children:"The suggestion that the incumbents (e.g., DraftKings and FanDuel) would offer Pick'em fantasy if it were legal is an excuse for being caught flat-footed by innovators like Underdog, who continued to focus on fantasy sports when the incumbents shifted overnight to being sportsbooks. These are not risk-averse companies. Without a competitive fantasy product, they have adopted convenient legal arguments that should not be immediately accepted as good-faith disagreements on the law."})]}),(0,a.jsx)("p",{className:c,children:"About Underdog"}),(0,a.jsx)("p",{className:p,children:"Underdog was founded in early 2020 by industry veterans. Today, we have a workforce of 300 employees across the United States. Underdog is perhaps best-known for our best-in-class Best Ball draft-style tournaments. In 2023, we offered and filled the largest fantasy sports contest in history with Best Ball Mania IV, totaling $15 million in prizes."}),(0,a.jsx)("p",{className:p,children:"We hold permits and licenses to offer fantasy sports contests in 17 states, many of which reviewed our contests as part of the licensing process. Beyond the usual licensing processes, in multiple states - Arizona, Indiana, Alabama, and Colorado - we operate Pick'em fantasy contests pursuant to express approval of the contest after searching reviews by the fantasy sports regulators. We anticipate launching our sports betting products in the near future, under sports betting licenses we hold in Colorado and Ohio with plans for other states in the works. Our mission: Build sports games that enhance how Americans interact with the sports they love, in a way that matches what matters to American sports fans."}),(0,a.jsx)("p",{className:p,children:"Underdog's games include our popular Pick'em fantasy contests. In these contests, the patron assembles a roster of athletes (two, three, four, or five), who must be from at least two different teams. The patron then selects which statistical metrics they care about (e.g., TDs scored, fantasy points, receiving yards), and then predicts whether each athlete will exceed a specific threshold. If the patron accurately predicts how their athletes will collectively perform, the patron wins."}),(0,a.jsx)("p",{className:c,children:"About Me"}),(0,a.jsxs)("p",{className:p,children:["Today, my"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.linkedin.com/in/nicholas-g-green/",text:"social media profile"})," ","says “Nicholas Green, General Counsel, Underdog,” but I've been working on fantasy sports and sports betting law for nearly a decade. In 2015, I was working in the New York office of Orrick, Herrington & Sutcliffe LLP when FanDuel, DraftKings, and the Fantasy Sports Trade Association engaged our firm to help clarify the legality of daily fantasy sports. Daily fantasy sports had come under attack by more than a dozen state attorneys general, fueled by a mix of politics and encouragement by brick-and-mortar gaming operators."]}),(0,a.jsx)("p",{className:p,children:"Our team worked to draft the langauge and pass the bills in state legislatures to ensure the continued operation of the daily fantasy sports industry. The effort succeeded with the passage of fantasy sports laws in Virginia, Tennessee, and subsequently in nearly two-dozen states that clarified the legality of paid fantasy sports."}),(0,a.jsxs)("p",{className:p,children:["The fantasy sports industry - indeed, the bulk of the sports entertainment industry - focused on a new goal when the U.S. Supreme Court invalidated the federal ban on sports betting in May 2018. Again, our team set to work on drafting the legislative language and passing sports betting legalization bills around the country for FanDuel and DraftKings. This effort also succeeded, leading to the enactment of mobile sports betting laws across the country. Others joined the DraftKings and FanDuel coalition, which now operate their lobbying coalition under Orrick's coordination as the Sports Betting Alliance. Parts of the story and"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.law360.com/articles/1285585/rising-star-orrick-s-nicholas-green",text:"my involvement"})," ","in both fantasy sports and sports betting legalization"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.nytimes.com/2022/11/20/business/sports-betting-lobbying-kansas.html",text:"has been well-documented."}),(0,a.jsx)("a",{href:"#footnote_two",rel:"noopener",children:(0,a.jsx)("sup",{children:"2"})})]}),(0,a.jsx)("p",{className:p,children:"In January 2022, I was a partner at Orrick, but decided I wanted to leave to be part of a team building a business. Now, I'm the General Counsel at Underdog Sports. I have a dog in the current fight over the future of paid fantasy sports - pun intended. But that hasn't changed my views on how the laws work. In fact, I would never have joined Underdog if I thought any of what they were offering violated the law. Like many, where I choose to work is one of the biggest investments I could make economically and professionally, and I chose to invest in Underdog because I understand how the laws we operate under work - in part because I helped draft them. Underdog's products fit squarely within U.S. fantasy and sports betting laws, and I have strong conviction in Underdog's ingrained culture of compliance. Our legal, government affairs, and compliance teams are best-in-class."}),(0,a.jsx)("p",{className:c,children:"Fantasy Sports Definitions Reflect that Fantasy Sports Have Always Had Many Formats."}),(0,a.jsx)("p",{className:p,children:"There is not - and never has been - a single format for online fantasy sports contests. The industry has included all manner of season-long and daily contests and all manner of draft, salary cap, best ball, “beat the score.” And, since at least 2012, single-patron fantasy contests."}),(0,a.jsxs)("p",{className:p,children:["When paid fantasy sports came under fire from state attorneys general, legislators, and others in 2015, the objective was not to legalize some forms of fantasy sports but not others. The objective was to clarify the legality of paid fantasy sports in the states that had questioned their legitimacy as skill contests. The debate was skill versus chance. And for good reason - under American common law, a contest of skill is not gambling regardless of whether it is played by peers or offered as a contest by an operator.",(0,a.jsx)("a",{href:"#footnote_three",rel:"noopener",children:(0,a.jsx)("sup",{children:"3"})})," ","Ultimately, the legality of fantasy sports was solidified. Most states now consider fantasy sports to be legal contests of skill, either in statutes allowing the operation of fantasy sports or through nearly a decade of history allowing them."]}),(0,a.jsx)("p",{className:p,children:"In this history, it's notable that single-patron fantasy formats are not new. StarStreet began offering a pick-em fantasy format in 2012, assets that DraftKings later acquired. Many others soon followed. Monkey Knife Fight and Betcha popularized the format now known as Pick'em in 2018 and 2019. Bally's and VividSeats acquired Monkey Knife Fight and Betcha, respectively, after what I assume is significant due diligence given the acquirers' regulatory status as a brick-and-mortar casino operator on one hand, and a major publicly traded company, on the other. PrizePicks began offering single-patron contests around the same time, with Underdog following in 2020."}),(0,a.jsxs)("p",{className:p,children:["Until recently, no one (at least no one within the industry, legislatures, or in regulatory bodies) questioned the legality of these offerings. As recently as 2022, FanDuel and DraftKings' Sports Betting Alliance touted Bally's fantasy sports offerings (i.e., Monkey Knife Fight's single-player contests in Maine and elsewhere) in pushing Maine to legalize sports betting and preserving fantasy sports as a distinct regulated category.",(0,a.jsx)("a",{href:"#footnote_four",rel:"noopener",children:(0,a.jsx)("sup",{children:"4"})})]}),(0,a.jsx)("p",{className:p,children:"What has changed, however, in recent months is that the incumbents have identified Underdog and others as actual competitive threats in both fantasy sports and, in the coming year, in sports wagering. Motivated by this competition backstory, FanDuel and DraftKings have suddenly taken a keen interest in characterizing our contests as illegal and have leveraged their significant industry and political connections to spread this erroneous narrative. This is not surprising - they are doing what monopolists have always done, which is to use whatever means available to them to impair innovators who threaten their market share. And we are a clear threat to their market share in fantasy sports, and pose an emerging threat as we build our sports betting technology and offerings."}),(0,a.jsx)("p",{className:c,children:"Underdog's Contests Meet the Elements Required for Fantasy Sports."}),(0,a.jsx)("p",{className:p,children:"Given the breadth of fantasy contests offered in the market in 2015 and beyond, there was a legislative challenge of defining fantasy sports in a way that captured the many contests available in the marketplace at the time. And keep in mind that this drafting largely occurred before anyone seriously contemplated that the U.S. Supreme Court would invalidate PASPA and return the issue of sports betting legalization to the states. The work of any good legislative attorney is to “future proof” legislation to avoid going back to the legislature over and over for amendments over the definition of fantasy sports, especially in a universe where sports wagering was not likely to occur."}),(0,a.jsxs)("p",{className:p,children:["To a tee, in states with statutes governing fantasy sports, the enacted legislation borrowed the definition of fantasy sports that Congress adopted in UIGEA, codified at 31 U.S.C. \xa7 5361(1)(E)(ix). ",(0,a.jsx)("span",{className:f,children:"Compare, e.g.,"})," Ariz. Rev. Stat. \xa7 5-1201 (2021); Mass. Gen. Laws ch. 12 \xa7 11M 1/2 (2022); Va. Code Ann. \xa7 59.1-556 (2016). The result was a remarkably uniform set of laws for an issue regulated by so many states. Under the common definition, a contest is fantasy sports if, among other requirements concerning entry fees and prize structure, the winning outcomes:"]}),(0,a.jsxs)("ol",{children:[(0,a.jsx)("li",{className:p,children:"reflect the relative knowledge and skill of the participants, i.e., the game is one of skill;"}),(0,a.jsx)("li",{className:p,children:"are determined predominantly by the accumulated statistical performance of individual athletes;"}),(0,a.jsx)("li",{className:p,children:"involve individual athletes who are participating in multiple real-world sporting or other events; and"}),(0,a.jsxs)("li",{className:p,children:["are ",(0,a.jsx)("span",{className:f,children:"not"})," based on the score, point-spread, or performance of teams or “solely on any single performance of an individual athlete.”"]})]}),(0,a.jsx)("p",{className:p,children:"Underdog's contests fit squarely within this common definition. To play Pick'em fantasy on the Underdog app, the patron must select a roster of multiple athletes, from different teams, and predict performance on the statistics of each athlete on the roster that are not based on the game score, point spread, or team performance. Further, a winning or losing outcome of the contest depends on the performance of all the rostered athletes, such that patrons cannot win or lose based solely on an individual athlete's prediction. None of Underdog's contests involve a single athlete or a single team. And Pick'em fantasy is proven to be a game of skill, as discussed in more detail below, where the outcomes reflect all participants' exercise of relative knowledge, both across all contests and in each individual contest among the participating patron and the operator."}),(0,a.jsx)("p",{className:c,children:"Fantasy Sports Are Not Sports Wagering As a Matter of Law."}),(0,a.jsx)("p",{className:p,children:"Nearly every sports wagering law passed in the United States since 2018 makes crystal clear that if a contest meets the definition of “fantasy sports,” that contest is not sports wagering. A contest is one or the other; it is legally impossible for a contest to be both."}),(0,a.jsx)("p",{className:p,children:"For most states that have authorized sports betting, whether the contest is fantasy sports is the threshold question. If the contest meets the definition of fantasy sports, then it is not a sports bet. Preserving fantasy contests was obviously a common thread of the model bills proposed by FanDuel and DraftKings in the post-PASPA push to legalize sports betting."}),(0,a.jsxs)("p",{className:p,children:["Arizona's statutes are typical. Passed in 2021 with the strong support of FanDuel, DraftKings, and their coalition of companies, the legislature defined “event [sports] wagering” to mean “accepting wagers on sports events or other events, portions of sports events or other events, the individual performance statistics of athletes in a sports event or combination of sports events.” Ariz. Rev. Stat. 5-1301(4)(a). A wager includes everything from single-game bets, parlays, in-play bets, and proposition bets."," ",(0,a.jsx)("span",{className:f,children:"Id."})," 5-1301(23)(b). But - and this is the most important point here - even if a fantasy sports contest might otherwise be characterized as being a sports wager, parlay, or proposition bet, the law is clear that a “fantasy sports contest as defined in [Arizona law]” is"," ",(0,a.jsx)("span",{className:f,children:"not"})," a sports wager."," ",(0,a.jsx)("span",{className:f,children:"See id."})," 5-1301(4)(b)."]}),(0,a.jsx)("p",{className:p,children:"Similar statutory language also exists in sports-betting states that do not have specific laws regulating fantasy sports contests and operators. North Carolina legalized sports betting in June 2023. Like Arizona, North Carolina's legislature expressly exempted fantasy sports from the definition of “sports wagering” by declaring that “[n]othing in this [Sports Wagering] Article shall apply to fantasy or simulated games or contests…” N.C. Gen. Stat. Ann. \xa7 18C-902(e). By clearly distinguishing fantasy sports from sports wagering, the North Carolina legislature ensured fantasy sports operators can continue offering fantasy sports without ambiguity."}),(0,a.jsxs)("p",{className:p,children:["Virtually every state uses this same construct that expressly exempts fantasy sports from the definition of sports wagering.",(0,a.jsx)("a",{href:"#footnote_five",rel:"noopener",children:(0,a.jsx)("sup",{children:"5"})})]}),(0,a.jsx)("p",{className:c,children:"Pick'Em Fantasy Is a Contest of Skill."}),(0,a.jsx)("p",{className:p,children:"Fantasy sports are legal across the country because they are contests of skill, and not games of chance. That is the basis for operating in the many states that do not have specific laws governing fantasy sports, meaning that the question of whether a contest is one of “skill” or “chance” applies the same regardless of the fantasy contest format (i.e., whether it's DraftKings' salary cap or Underdog's Pick'em fantasy). This skill versus chance dividing line is also the legal foundation for states that authorized fantasy sports in statutes."}),(0,a.jsxs)("p",{className:p,children:["Underdog engaged the same statistician as DraftKings to employ the same methodology to determine whether Underdog's contests are, in fact, contests of skill. He agreed that they are. Dr. Zvi Gilula is a Professor (Emeritus) of Statistics at Hebrew University, a Visiting Professor at the University of Chicago, and elected fellow of the Royal Statistical Society and the American Statistical Association. He validated DraftKings' salary cap formats as contests of skill in 2015. DraftKings' lawyers relied on that report in litigation in"," ",(0,a.jsx)(i.Z,{className:d,href:"https://deadline.com/wp-content/uploads/2015/11/draftkings-tro-nov-16-wm.pdf",text:"New York"})," ","and"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.legalsportsreport.com/wp-content/uploads/2016/03/Orig-Petition.pdf",text:"Texas."})," ","With respect to DraftKings' contests, he found that “one MUST conclude that the fantasy games offered by DraftKings have an inherent and vast character of skill where chance is ",(0,a.jsx)("span",{className:f,children:"overwhelmingly immaterial"})," to the probability of winning in such games.”",(0,a.jsx)("a",{href:"#footnote_six",rel:"noopener",children:(0,a.jsx)("sup",{children:"6"})})]}),(0,a.jsxs)("p",{className:p,children:["Dr. Gilula has likewise validated Underdog's Pick'em fantasy games as contests of skill using the same methodology he employed for DraftKings. An abstract of his findings is"," ",(0,a.jsx)(i.Z,{className:d,href:`${h.$}/Zvi-Gilula-abstract.pdf`,text:"available here"}),". He concluded, as he did in 2015 with respect to DraftKings' contests, that “the element of chance is IMMATERIAL, and skill predominates, in determining the winning of games between typical users.” He also found that with respect to all versions of the game - whether the patron builds a roster of two, three, four, or five athletes - “I safely and strongly conclude that the game has intrinsic character that enable skillful users to have an advantage.”"]}),(0,a.jsx)("p",{className:p,children:"Anyone who plays Underdog's Pick'em game knows the value of knowledge and skill in assembling a roster of athletes and predicting how they will perform. The structure of our contest enables patrons to exercise skill to an unusual degree, far more than in draft or salary cap contests. Salary cap drafts and other formats restrict participants to a series of roster criteria, scoring, pool size, player value, and other factors that may handicap their ability to put their particular knowledge and skills to work - not to mention the inherent “chanciness” of draft order on snake drafts. In Underdog's Pick'em fantasy game, by contrast, patrons can deploy their particularized knowledge and skill in building an athlete roster and statistical criteria in a way that is impossible in draft-style fantasy formats."}),(0,a.jsx)("p",{className:c,children:"Pick'Em Fantasy Is Not A Sports Betting Parlay."}),(0,a.jsx)("p",{className:p,children:"The incumbents have leaned into saying that “pick'em fantasy is just a parlay masquerading as fantasy sports.” They're wrong. There are a series of strict, immutable rules that govern a fantasy sports contest. In any fantasy contest, the roster cannot have athletes from one team; you can only predict the performance of individual athletes; and winning outcomes must be based upon the accumulated performance of those athletes."}),(0,a.jsx)("p",{className:p,children:"Those immutable requirements are why customers cannot replicate their casino sportsbook options on a fantasy platform like Underdog. Anyone who has ever parlayed bets on a casino sportsbook knows the difference between pick'em fantasy and sports wagering."}),(0,a.jsxs)("ul",{children:[(0,a.jsx)("li",{className:p,children:"On a casino sportsbook, you can place a wager based on the performance of a single athlete. Not so on Underdog."}),(0,a.jsx)("li",{className:p,children:"On a casino sportsbook, you can place a wager based on the performance of athletes from a single athletic team. Not so on Underdog."}),(0,a.jsx)("li",{className:p,children:"On a casino sportsbook, you can combine wagers on an athlete with any number of other bets - game bets, team props, first-to-score, novelty bets, you name it. Not so on Underdog."}),(0,a.jsx)("li",{className:p,children:"On a casino sportsbook, the operator presents the consumer with a pre-selected set of parlay bets encompassing players, teams, and games. Not so on Underdog."})]}),(0,a.jsx)("p",{className:p,children:"More to the point, just because a sportsbook decides to offer something on their platform that qualifies as fantasy sports does not mean it magically becomes “sports betting.” That's a product and business choice. FanDuel could decide tomorrow to put their salary cap contests in their sportsbook app. That would not make DraftKings' salary cap contents “sports wagering.” The legal analysis does not look at what operators choose to do voluntarily."}),(0,a.jsx)("p",{className:p,children:"Underdog uniquely understands the limitations of fantasy sports as a distinct category. That's why we are devoting substantial resources to creating one of the first American-built sportsbooks, so that we can deliver consumer-centric experiences that we can never offer as a fantasy sports operator."}),(0,a.jsx)("p",{className:c,children:"Law Governs Over Supposed Similarities."}),(0,a.jsxs)("p",{className:p,children:["Whether a contest “looks” or “feels like” sports betting does not affect the legal analysis. In ordinary language, putting money on a contingent outcome is “gambling.” If a group of friends play golf and put money on each hole, most people would say in a colloquial sense that the agreement is a “wager” and therefore “gambling” even though it's a perfectly legal contest of skill, is not subject to the sports wagering laws, and is not illegal in most places. For years,"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.legalsportsreport.com/30754/draftkings-william-hill-ceo-spat/",text:"brick-and-mortar casino interests called paid fantasy sports"})," ","- the contests that built FanDuel and DraftKings - gambling and sports betting. That did not make it so, as courts and legislatures have since confirmed."]}),(0,a.jsx)("p",{className:p,children:"The legal analysis turns solely on the statutory text, not what something “feels like” - and especially not whether something “feels like” sports betting in hindsight with the repeal of PASPA."}),(0,a.jsx)("p",{className:p,children:"Consider this statement from Jason Robins, Founder, CEO, and controlling shareholder of DraftKings, when he was defending daily fantasy sports from its detractors:"}),(0,a.jsx)("p",{className:g,children:"Here's what I'm sick and tired of - is when people ask a commentator, or someone in the news media, “Is this gambling?” The answer they're giving is their own answer based on a subjective view of what constitutes gambling in their mind. There are people that say playing a game of chess, if you challenge your friend for ten bucks, is gambling. There are others who will say that something like online poker absolutely is not gambling."}),(0,a.jsxs)("p",{className:g,children:["What I will say is that's not the right question. The right question is, is it legal or not under the laws of the state under which you operate? That's something that I think is the more relevant question.",(0,a.jsx)("a",{href:"#footnote_seven",rel:"noopener",children:(0,a.jsx)("sup",{children:"7"})})]}),(0,a.jsx)("p",{className:p,children:"Now that Mr. Robins doesn't like the answer, he forgets to ask the right question."}),(0,a.jsx)("p",{className:c,children:"There Is No “Against the House” Dividing Line in Federal or State Law."}),(0,a.jsx)("p",{className:p,children:"Some have proposed that the difference between fantasy sports and sports wagering depends on whether the contest is “against the house” or is peer-to-peer. Here's why there is no legal basis for this distinction."}),(0,a.jsx)("p",{className:p,children:"First, proponents of this view rely on convoluted readings that turn on singular and plural constructions in state statutes, as well as federal law, with shifting views based on the terms “contests,” “players,” and “participants”. They are literally trying to argue that an “s” changes the entire construct of what can be a fantasy contest. The far more straightforward reading is that the federal statute refers collectively to the knowledge and skill of all of the participants in all contests. You can't give a dispositive effect to the plural of one word while ignoring the plural nouns in the rest of the clause."}),(0,a.jsxs)("p",{className:p,children:["Second, proponents of this interpretation neglect a fundamental concept of statutory construction: We do not ascribe critical importance to textual minutiae or adopt interpretations that require so much work,",(0,a.jsx)("span",{className:f,children:"cf. Whitman v. American Trucking Associations, Inc."}),", 531 U.S. 457, 468 (holding that Congress “does not, one might say, hide elephants in mouseholes”), especially when Congress and the states have expressly told courts and regulators to use plurals and singulars interchangeably, see 1 U.S.C. \xa7 1;"," ",(0,a.jsx)("span",{className:f,children:"e.g."}),", Tenn. Code \xa7 1-3-104(c). Notably, other gaming laws show that when Congress wants to specifically define contests involving operators, it knows how to do so. ",(0,a.jsx)("span",{className:f,children:"See"})," 15 U.S.C. \xa7 3002(13) (clarifying that parimutuel is wagering among participants and “not against the operator” under the Interstate Horseracing Act); 28 U.S.C. \xa7 3704 (excluding parimutuel from PASPA)."]}),(0,a.jsx)("p",{className:p,children:"Third, single-patron fantasy was not a new concept when the battle raged among DFS, states, and brick-and-mortar casinos from 2015 to 2017. More importantly, these games were an established and important part of the fantasy sports landscape when the same states legalized sports betting and elected not to modify the definitions of fantasy sports as part of those efforts. More than 25 states enacted legalized sports betting laws, most of which exempted fantasy sports from their definitions after fantasy offerings from Monkey Knife Fight/Bally's, Betcha/Vivid, PrizePicks or Underdog were already on the scene. The purpose of these laws was to legalize mobile sports wagering while preserving the status quo of the fantasy sports industry. If the legislatures - or the interests calling for legalization of sports betting - wanted to eliminate a key pillar of the fantasy sports industry, they would have done so clearly and expressly. They did not."}),(0,a.jsx)("p",{className:p,children:"Fourth, proponents rely on the concept of “relative knowledge” to say that it must be a peer-to-peer style contest. Again, these proponents attempt to discern meaning where none exists by placing emphasis on the word “relative,” which is undefined in UIGEA and most state fantasy-sports laws. The legislatures' use of the word “relative” does not mean that all contests must be peer-to-peer; rather, it reflects an intent for “winning outcomes” to be based on what a player knows, and how skillful a player is. The word “relative” is used to indicate that outcomes should be commensurate with a player's knowledge and skill—the more a player knows, and the more skillful a player is, the better the player's results should be. That is undoubtedly the case with Underdog's Pick'em fantasy contests."}),(0,a.jsxs)("p",{className:p,children:["Finally, those who espouse this interpretation show a misunderstanding of the role that fantasy operators have always played in paid fantasy sports contests. Nearly every law in this country gives the operator the ability and largely unfettered discretion to decide how rosters should be constructed, scoring criteria, draft sizes, and draft criteria and order. Some have said so expressly.",(0,a.jsx)("span",{className:f,children:"See"})," Ala. Code \xa7 8-19F-3(b) (“The regulator may not adopt rules limiting or regulating the rules or administration of an individual fantasy contest, the statistical makeup of a fantasy contest, or the digital platform of a fantasy contest operator.”). In any paid fantasy contest, the operator sets the amount of the entry fee and the prize structure - and with guaranteed contests the operator bears the burden of awarding the pre-set prizes even if the contest does not fill (a concept known as “overlay”). The peer-to-peer versus “against the house” construct does not do the work as a factual matter that proponents believe that it does."]}),(0,a.jsx)("p",{className:c,children:"If Pick'em Fantasy Is Legal, Why Don't DraftKings and FanDuel Offer It?"}),(0,a.jsx)("p",{className:p,children:"I'll confess to not knowing why DraftKings and FanDuel do not have fantasy contests that are similar to Pick'em fantasy; I do not have any public or non-public information on that issue. Even though they have said publicly that they do not believe the contests fit within the definitions of state law, there is nothing legally binding them from reconsidering their conclusion now."}),(0,a.jsx)("p",{className:p,children:"What I do know is what is obvious from their public statements, shareholder filings, and activities in the past several years. The incumbents shifted their focus and resources rapidly from fantasy sports to the much greater revenue opportunities in mobile sports wagering. If you believe that the future of your business is sports betting, why bother innovating in fantasy sports? Or maybe they did not see a business case given the relatively stagnant growth in Monkey Knife Fight and VividPicks' businesses (whose parent brand, Vivid, has DraftKings as an investor). Regardless, they were caught flat-footed by startups like Underdog who continued to see opportunities in fantasy. Leaning on their legal argument against Pick'em is at the very least a convenient excuse for their prior miscalculation. Now, they've seemingly determined that trying to stop us and our peers is more valuable to them than offering the same contests."}),(0,a.jsxs)("p",{className:p,children:["The public perception is that these are not inherently cautious companies. The current debate over Pick'em fantasy is whether it qualifies as fantasy sports; the debate in 2015 and subsequent years was a much more fundamental and serious question of whether fantasy sports could operate at all without running afoul of gambling laws. Even in the midst of that debate, DraftKings (and later, FanDuel) expanded to offering single-event contests on sports like a NASCAR race and a golf tournament,"," ",(0,a.jsx)(i.Z,{className:d,href:"https://www.legalsportsreport.com/5580/why-draftkings-fanduel-offer-different-sports/",text:"despite reported concerns that doing so violates UIGEA."})]}),(0,a.jsxs)("p",{className:p,children:["And even now, DraftKings has spent years touting its Reignmakers product, which at least one state (Pennsylvania)"," ",(0,a.jsx)(i.Z,{className:d,href:"https://sportshandle.com/pennsylvania-bans-draftkings-reignmakers/",text:"has shut down as an illegal fantasy offering."})," ","Reignmakers introduces consideration (purchase of a “pack” of NFTs) and a random number generator into the drafting of athletes (the players within the “pack” are assigned by probabilistic chance). FanDuel for its part is using supposedly “skill-based” Tetris, Boggle, and other games in"," ",(0,a.jsx)(i.Z,{className:d,href:"https://sbcamericas.com/2023/09/01/fanduel-faceoff-skill-games-gronk/",text:" its unregulated FanDuel Faceoff"})," ","product to gateway users into online casino. These are not risk-free products from a legal perspective."]}),(0,a.jsx)("p",{className:"styles__starDivider__UM5OO",children:"* * *"}),(0,a.jsx)("p",{className:p,children:"Underdog's Pick'em fantasy contests are undoubtedly popular, as are similar fantasy games offered by other innovators in the fantasy sports industry. The legal basis for offering these games is clear and established by nearly a decade of laws passed to clarify the legality of fantasy sports, and to preserve fantasy sports as a category of games distinct from sports wagering. Underdog's contests meet the letter and spirit of the laws defining fantasy sports, are contests of skill, and are not sports wagering - regardless of contrary arguments offered by industry incumbents who are motivated primarily by avoiding competition and have adopted legal positions to fit that interest."}),(0,a.jsxs)("div",{className:"styles__letterSignOff__evYh9",children:[(0,a.jsx)("img",{alt:"Nick Green signature",className:"styles__signature__n3fum",src:`${h.$}/nick-green-signature.png`}),(0,a.jsx)("p",{className:"styles__signOff__ApgaG",children:"Nicholas Green, General Counsel"})]}),(0,a.jsx)("div",{className:"styles__divider___OT3m"}),(0,a.jsx)("a",{id:"footnote_one",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"1"})," This paper does not endeavor to address every law that might apply to Underdog's contests but, rather, to address the arguments I've heard offered in opposition to them from industry competitors."]})}),(0,a.jsx)("a",{id:"footnote_two",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"2"})," The facts reported here are available in publicly available documents and news reporting and should not be interpreted as involving attorney-client privileged information."]})}),(0,a.jsx)("a",{id:"footnote_three",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"3"})," ",(0,a.jsx)("span",{className:f,children:"See"})," Edelman et al.,",(0,a.jsx)("span",{className:f,children:"U.S. Fantasy Sports Law: Fifteen Years After UIGEA,"})," ","83 Ohio. St. L.J. 117, 128-29 (2022);",(0,a.jsx)("span",{className:f,children:"see also Las Vegas Hacienda v. Gibson"}),", 359 P.2d 85, 87 (Nev. 1961) (affirming the trial court's finding that a golf course operator's offer for consideration of a prize for making a hole-in-one was a contest of skill and not an illegal game of chance);"," ",(0,a.jsx)("span",{className:f,children:"Arizona v. Amer. Holiday Ass'n, Inc.,"})," 727 P.2d 807 (Ariz. 1986) (concluding that payment of consideration to enter into a skill-based word game sponsored by a corporation was not an illegal game of chance or gambling)."]})}),(0,a.jsx)("a",{id:"footnote_four",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"4"})," ",(0,a.jsx)("span",{className:f,children:"See"})," Written Testimony of the Sports Betting Alliance on LD 585 before the Maine Joint Standing Committee on the Judiciary (Feb. 17, 2022), ",(0,a.jsx)("span",{className:f,children:"available at"}),"https://legislature.maine.gov/bills/getTestimonyDoc.asp?id=10005826."]})}),(0,a.jsx)("a",{id:"footnote_five",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"5"})," ",(0,a.jsx)("span",{className:f,children:"See, e.g.,"})," Ariz. Rev. Stat. \xa7 5-1301(4)(b) (2021); Colo. Rev. Stat. \xa7 44-13-1501(12)(b) (2019); D.C. Act 22-594(c)(17) (2019); ",(0,a.jsx)("span",{className:f,children:"Dew-Becker v. Wu,"})," 2020 IL 124472, \xb6 20 n.1 (finding “[t]he Sports Wagering Act does not address or regulate DFS contests”); Ind. Code 4-38-2-18 (2019); S.B. 84 \xa7 13(a)(9)(1) (Kansas 2022); L.D. 585 \xa7 1202(14) (Maine 2022); Md. Code, State Gov't \xa7 9-1E-01(i)(2)(ii) (2021); Mass. General Laws c.23N \xa7 3 (2022); Neb. Rev. Stat. \xa7 9-1103(3)(b) (2021); N.H. Rev. Stat \xa7 287-I:16 (2019); N.J. Rev. Stat. \xa7 5:12A-10 (2018); N.C. G.S. \xa7 18C-902(e) (2023); Ohio Rev. Code \xa7 3775.01(3)(d) (2021); 4 Pa.C.S. \xa7 13C01(7) (2017); Va. Code Ann. \xa7 58.1-4030 (2020); W. Va. Stat. \xa7 29-22D-3(23)(G) (2018); Wyo. Stat. \xa7 9-24-101(a)(xii)(D) (2021)."]})}),(0,a.jsx)("a",{id:"footnote_six",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"6"})," DraftKings' Mem. of Law in Support of TRO and Article 78 Petition at p. 16, ",(0,a.jsx)("span",{className:f,children:"DraftKings, Inc. v. Schneiderman,"})," N.Y. Sup. Ct. Index No. 102014-15 (Nov. 16, 2015),"," ",(0,a.jsx)("span",{className:f,children:"available at"})," ","https://deadline.com/wp-content/uploads/2015/11/draftkings-tro-nov-16-wm.pdf"]})}),(0,a.jsx)("a",{id:"footnote_seven",children:(0,a.jsxs)("p",{className:m,children:[(0,a.jsx)("sup",{children:"7"})," Daniel Barbarisi,"," ",(0,a.jsx)("span",{className:f,children:"Dueling With Kings: High Stakes, Killer Sharks, and the Get-Rich Promise of Daily Fantasy Sports"})," ","at pp. 127 (2017)."]})})]})})]}))}}]);
